31	    private OwnerCustomerCode() {
32	    }
33	
34	    /** The {@code <REGION>-<HASH8>} customer code for {@code owner}. */
35	    public static String customerCode(Owner owner) {
36	        String region = OwnerRegion.localityOf(owner.getCity(), owner.getPostcode());
37	        return region + "-" + hash8(owner.getTelephone(), owner.getLastName());
38	    }
39	
40	    /**
41	     * The {@code HASH8} segment: the first eight upper-case hex characters of the SHA-256 of the
42	     * normalized (E.164) telephone concatenated with the last name.
43	     */
44	    static String hash8(String telephone, String lastName) {
45	        String normalizedTelephone = OwnerTelephone.toE164(telephone);
46	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
47	                + (lastName == null ? "" : lastName);
48	        try {
49	            byte[] digest = MessageDigest.getInstance("SHA-256")
50	                    .digest(key.getBytes(StandardCharsets.UTF_8));
51	            StringBuilder sb = new StringBuilder(8);
52	            for (int i = 0; i < 4; i++) {
53	                sb.append(String.format("%02X", digest[i]));
54	            }
55	            return sb.toString();
56	        }
57	        catch (NoSuchAlgorithmException ex) {
58	            throw new IllegalStateException("SHA-256 not available", ex);
59	        }
60	    }
