62	    /**
63	     * De-duplicates {@code base} against the {@code existing} customer codes: returns {@code base}
64	     * unchanged when it is not already taken, otherwise appends {@code -<n>} with the smallest
65	     * {@code n} of 2 or more that makes the code unique.
66	     */
67	    public static String deduplicate(String base, Set<String> existing) {
68	        if (!existing.contains(base)) {
69	            return base;
70	        }
71	        for (int n = 2; ; n++) {
72	            String candidate = base + "-" + n;
73	            if (!existing.contains(candidate)) {
74	                return candidate;
75	            }
76	        }
77	    }
